@import "tailwindcss";

/* Confirmed palette — sampled from the founder's site (spec §7.1).
   These names become Tailwind utilities: bg-blue, text-navy, bg-pale, text-red. */
@theme {
  --color-blue: #0000FF;
  --color-navy: #00000A;
  --color-red: #FF0504;
  --color-pale: #FFFBB5;
  --color-success: #16A34A;

  --font-display: var(--font-bricolage), ui-sans-serif, system-ui, sans-serif;
  --font-sans: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --font-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;

  --radius-pill: 999px;
}

@layer base {
  html { scroll-behavior: smooth; }
  body {
    @apply bg-white text-black font-sans antialiased;
  }
  ::selection { background: var(--color-pale); }
  :focus-visible { outline: 2px solid var(--color-blue); outline-offset: 2px; }
}

/* Section gradients per spec §7.2 — soft white → pale yellow, never a flat fill. */
@utility bg-fade-pale {
  background-image: linear-gradient(180deg, #ffffff 0%, var(--color-pale) 140%);
}
@utility bg-nav-gradient {
  background-image: linear-gradient(90deg, var(--color-blue) 0%, var(--color-navy) 100%);
}
@utility text-balance-pretty {
  text-wrap: balance;
}

/* Marquee — two identical groups + -50% translate = seamless loop. */
@keyframes marquee-roll {
  from { transform: translateX(0); }
  to { transform: translateX(-50%); }
}
.marquee-track {
  display: inline-flex;
  white-space: nowrap;
  animation: marquee-roll 30s linear infinite;
}
@media (prefers-reduced-motion: reduce) {
  .marquee-track { animation: none; }
  * { transition-duration: 0.01ms !important; animation-duration: 0.01ms !important; }
}
