/** Haversine distance in km. */
export function distanceKm(aLat: number, aLng: number, bLat: number, bLng: number): number {
  const R = 6371;
  const dLat = ((bLat - aLat) * Math.PI) / 180;
  const dLng = ((bLng - aLng) * Math.PI) / 180;
  const s =
    Math.sin(dLat / 2) ** 2 +
    Math.cos((aLat * Math.PI) / 180) * Math.cos((bLat * Math.PI) / 180) * Math.sin(dLng / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(s));
}

/** Bounding box for the indexed prefilter. ~0.35° ≈ 39km — covers Lagos comfortably. */
export function bbox(lat: number, lng: number, delta = 0.35) {
  return { minLat: lat - delta, maxLat: lat + delta, minLng: lng - delta, maxLng: lng + delta };
}

/** Fallback centre when geolocation is denied: Lagos. */
export const LAGOS = { lat: 6.5244, lng: 3.3792 };
